def get_max_sum(n):
    """
    Finds the maximum sum possible by using the given equation f(n) = max( (f(n/2) + f(n/3) + f(n/4) + f(n/5)), n).

    Args:
        n: The input integer.

    Returns:
        The maximum sum possible.
    """
    if n <= 0:
        return 0
    if n == 1:
        return 1
    if n == 2:
        return 2
    if n == 3:
        return 3
    if n == 4:
        return 4
    if n == 5:
        return 5

    val1 = get_max_sum(n // 2)
    val2 = get_max_sum(n // 3)
    val3 = get_max_sum(n // 4)
    val4 = get_max_sum(n // 5)

    return max(val1 + val2 + val3 + val4, n)

