def count_binary_seq(n):
    """
    Find the count of all binary sequences of length 2n such that sum of first n bits is same as sum of last n bits.

    For example:
    count_binary_seq(1) == 2
    count_binary_seq(2) == 6
    count_binary_seq(3) == 20
    """
    dp = {}

    def solve(index, sum1, sum2):
        if index == 2 * n:
            if sum1 == sum2:
                return 1
            else:
                return 0

        if (index, sum1, sum2) in dp:
            return dp[(index, sum1, sum2)]

        ans = 0
        if index < n:
            ans += solve(index + 1, sum1 + 1, sum2)
            ans += solve(index + 1, sum1, sum2)
        else:
            ans += solve(index + 1, sum1, sum2 + 1)
            ans += solve(index + 1, sum1, sum2)

        dp[(index, sum1, sum2)] = ans
        return ans

    return solve(0, 0, 0)

