def dict_depth(d):
    """
    Finds the depth of a dictionary.

    Args:
        d (dict): The dictionary to find the depth of.

    Returns:
        int: The depth of the dictionary.
    """
    if not isinstance(d, dict):
        return 0
    else:
        max_depth = 1
        for k, v in d.items():
            if isinstance(v, dict):
                max_depth = max(max_depth, 1 + dict_depth(v))
        return max_depth

