def count_binary_seq(n):
    """
    Find the count of all binary sequences of length 2n such that sum of first n bits is same as sum of last n bits.

    For example:
    count_binary_seq(1) == 2
    count_binary_seq(2) == 6
    count_binary_seq(3) == 20
    """
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(n + 1):
        for j in range(n + 1):
            if i > 0:
                dp[i][j] += dp[i - 1][j]
            if j > 0:
                dp[i][j] += dp[i][j - 1]

    result = 0
    for i in range(n + 1):
        result += dp[n][i] * dp[n][i]

    return result

