    """
    Finds the nth number in the Newman-Conway sequence.

    Args:
        n: The index of the number to find (1-based).

    Returns:
        The nth number in the sequence.
    """

    if n == 1:
        return 1
    elif n == 2:
        return 2
    elif n == 3:
        return 3

    seen = {1, 2, 3}
    seq = [1, 2, 3]

    i = 4
    while i <= n:
        next_val = seq[-1] + seq[-2] - seq[-3]
        if next_val not in seen:
            seq.append(next_val)
            seen.add(next_val)
            i += 1
        else:

