def count_binary_seq(n):
    """
    Finds the count of all binary sequences of length 2n such that sum of first n bits is same as sum of last n bits.

    Args:
        n: The length of each half of the binary sequence.

    Returns:
        The count of binary sequences satisfying the condition.
    """
    if n == 0:
        return 1

    dp = [[0 for _ in range(n + 1)] for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(n + 1):
        for j in range(n + 1):
            if i > 0:
                dp[i][j] += dp[i - 1][j]
            if j > 0:
                dp[i][j] += dp[i][j - 1]

    total_count = 0
    for i in range(n + 1):
        total_count += dp[n][i] * dp[n][i]

    return total_count

