def sequence(n):
    """
    Finds the nth number in the Newman-Conway sequence.

    Args:
        n: The index of the desired number in the sequence (starting from 0).

    Returns:
        The nth number in the Newman-Conway sequence.
    """
    if n == 0:
        return 1
    elif n == 1:
        return 1
    elif n == 2:
        return 1
    else:
        a = [1, 1, 1]
        for i in range(3, n + 1):
            next_val = a[i - 1] + a[i - 2] + a[i - 3]
            a.append(next_val)
        return a[n]

