def is_undulating(n):
    """
    Check whether the given number is undulating or not.
    An undulating number is a number whose adjacent digits alternate between increasing and decreasing.
    For example, 121 is undulating, but 123 is not.
    Args:
        n: The number to check.
    Returns:
        True if the number is undulating, False otherwise.
    """
    s = str(n)
    if len(s) < 3:
        return False
    for i in range(1, len(s) - 1):
        if i % 2 == 1:
            if int(s[i]) <= int(s[i - 1]) or int(s[i]) <= int(s[i + 1]):
                return False
        else:
            if int(s[i]) >= int(s[i - 1]) or int(s[i]) >= int(s[i + 1]):
                return False
    return True

